#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

using i128 = __int128_t;

void printInt128(i128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    string result;
    while (value > 0) {
        result += char('0' + value % 10);
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long wInput, mInput, kInput;
    cin >> wInput >> mInput >> kInput;

    i128 w = wInput;
    i128 m = mInput;
    i128 k = kInput;
    i128 count = 0;

    int digits = 1;
    i128 nextPower = 10;
    while (m >= nextPower) {
        nextPower *= 10;
        ++digits;
    }

    while (w >= k * digits) {
        i128 available = nextPower - m;
        i128 costPerNumber = k * digits;
        i128 canBuy = w / costPerNumber;
        i128 take = min(available, canBuy);

        count += take;
        w -= take * costPerNumber;
        m += take;

        if (take < available)
            break;

        nextPower *= 10;
        ++digits;
    }

    printInt128(count);
    cout << '\n';
    return 0;
}

