#include <iostream>
#include <algorithm>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int digits(i128 n) {
    if (n == 0) return 1;
    int result = 0;
    while (n > 0) {
        ++result;
        n /= 10;
    }
    return result;
}

void print(i128 n) {
    if (n == 0) {
        cout << 0;
        return;
    }
    string s;
    while (n > 0) {
        s += char('0' + n % 10);
        n /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 wInput, mInput, kInput;
    cin >> wInput >> mInput >> kInput;

    i128 budget = wInput;
    i128 current = mInput;
    i128 k = kInput;
    i128 count = 0;

    while (budget > 0) {
        int d = digits(current);
        i128 cost = k * d;

        if (cost > budget)
            break;

        i128 nextPower = 1;
        for (int i = 0; i < d; ++i)
            nextPower *= 10;

        i128 available = nextPower - current;
        i128 affordable = budget / cost;
        i128 take = min(available, affordable);

        count += take;
        current += take;
        budget -= take * cost;

        if (take < available)
            break;
    }

    print(count);
    cout << '\n';
    return 0;
}

